<?php require_once __DIR__.'/includes/functions.php';require_role(['admin','staff']);class RequestQueue{private array $items=[];public function enqueue(array $item):void{$this->items[]=$item;}public function dequeue():?array{return array_shift($this->items);}public function peek():?array{return $this->items[0]??null;}public function size():int{return count($this->items);}public function all():array{return $this->items;}}$queue=new RequestQueue();$rs=$db->query("SELECT t.id,t.type,t.requested_at,u.name,b.title FROM transactions t JOIN users u ON u.id=t.user_id JOIN books b ON b.id=t.book_id WHERE t.status='pending' ORDER BY t.requested_at ASC");while($r=$rs->fetch_assoc())$queue->enqueue($r);$peek=$queue->peek();$first=$queue->dequeue();$title='Queue demonstration';require 'includes/header.php';?><h1>Data structure: FIFO request queue</h1><div class="panel"><p>This real feature uses a PHP queue (array-backed FIFO) to represent pending requests in oldest-first order. Staff processes the earliest request first, supporting fair and transparent approvals.</p><div class="grid"><div class="card"><div class="muted">Queue size before dequeue</div><div class="stat"><?=$queue->size()+($first?1:0)?></div></div><div class="card"><div class="muted">Next item (peek)</div><div><?= $peek?'Request #'.e($peek['id']):'No pending requests'?></div></div><div class="card"><div class="muted">Dequeued / next to process</div><div><?=$first?'Request #'.e($first['id']):'Queue is empty'?></div></div></div><h2>Pending requests in FIFO order</h2><div class="table-wrap"><table><tr><th>Position</th><th>Request ID</th><th>Requester</th><th>Book</th><th>Type</th><th>Requested at</th></tr><?php $i=1;foreach($queue->all() as $r):?><tr><td><?=$i++?></td><td>#<?=$r['id']?></td><td><?=e($r['name'])?></td><td><?=e($r['title'])?></td><td><?=e($r['type'])?></td><td><?=e($r['requested_at'])?></td></tr><?php endforeach;?></table></div><p><b>Complexity:</b> enqueue is amortized O(1); dequeue with PHP array_shift is O(n) because remaining elements are reindexed; peek is O(1); size is O(1). This queue is built from actual pending database requests rather than treating a database table alone as the data structure.</p></div><?php require 'includes/footer.php';?>
